import { defineConfig } from 'vite';

/**
 * Bundles the deterministic engine + replay verifier into api/_engine.js so the serverless
 * functions can re-run submitted replays without a TypeScript toolchain at runtime.
 * Regenerated by `npm run build:engine` (part of `npm run build`).
 */
export default defineConfig({
  publicDir: false,
  build: {
    lib: { entry: 'src/replay.ts', formats: ['es'], fileName: () => '_engine.js' },
    outDir: 'api',
    emptyOutDir: false,
    minify: false,
    target: 'node18',
    sourcemap: false,
  },
});
